function issue(inv){openDialog(`<h2>Issue ${inv.data.tax_invoice?'tax invoice':'invoice'}</h2><p>This locks the document details and creates its PDF. The assigned number will never be reused.</p>${field('Document number · leave blank for automatic','number','','text',false,'maxlength="80" placeholder="Automatic company sequence"')}<label class="check"><input type="checkbox" required><span>I reviewed the details, currency, and total of <b>${money(inv.total_minor,inv.currency)}</b>.</span></label>${inv.data.tax_invoice?'<label class="check"><input name="tax_confirmed" type="checkbox" required><span>I confirm the full invoice amount has reached the VAT tax point today. I understand LocalBooks cannot issue credit notes.</span></label>':''}`,async f=>{await api('/api/issue',{id:inv.id,number:f.get('number'),revision:inv.revision,tax_confirmed:f.get('tax_confirmed')==='on'});await refresh();render();notify('Document issued and PDF saved.')});$('#dialog button[type=submit]').textContent='Issue document'}
function payment(inv){location.hash='payment/'+inv.id}
function reasonDialog(title,description,action){openDialog(`<h2>${title}</h2><p>${description}</p>${area('Reason','reason','','required maxlength="500"')}`,async f=>{await action(f.get('reason'));await refresh();render();notify('Correction recorded.')})}
function fileBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)})}
function attach(inv,pid,category='general'){openDialog(`<h2>Attach ${category==='withholding_certificate'?'withholding certificate':pid?'payment proof':'original document'}</h2><p>The file is copied into the local database. This does not change the payment status.</p><label class="field">File · up to 20 MB<input name="file" type="file" required></label>`,async f=>{const file=f.get('file');if(!file.size||file.size>20*1024*1024)throw new Error('Choose a file up to 20 MB.');await api('/api/attach',{id:inv.id,payment_id:pid,category,name:file.name,content:await fileBase64(file)});await refresh();render();notify('Attachment saved locally.')})}
function renderBackup(){
  $('#main').innerHTML=head('Backup & restore','Save or restore records for all companies.')+`<div class="intro">
    <section class="card"><h2>Save a backup</h2><p>Includes all companies, records, and attached files.</p><a class="button" href="/api/backup">Download backup</a><p class="hint">Keep a copy on another drive. Backups contain private financial records and are not encrypted.</p></section>
    <section class="card"><h2>Restore a backup</h2><p>Replace all current records with a saved LocalBooks backup. A safety copy of your current records is saved first.</p><button class="secondary" id="restore">Choose backup…</button></section>
    <details class="card"><summary>Where your data is stored</summary><div class="backup-path">${esc(state.data_path)}</div><p class="hint">Your records stay on this Mac when you move the app. To move records to another Mac, download a backup and restore it there.</p></details>
  </div>`;
  $('#restore').onclick=()=>{
    openDialog(`<h2>Restore backup</h2><p>This replaces records for <b>all companies</b> with the selected backup. LocalBooks checks the file and saves a safety copy of your current records before restoring.</p><label class="field">Backup file · .sqlite3<input name="file" type="file" accept=".sqlite3" required></label>${field('Type RESTORE to confirm','confirmation','','text',true,'pattern="RESTORE" autocomplete="off"')}`,async f=>{
      const file=f.get('file');
      if(!file.size)throw new Error('Choose a LocalBooks backup.');
      const response=await fetch('/api/restore',{method:'POST',headers:{'Content-Type':'application/vnd.sqlite3','X-LocalBooks-Confirmation':f.get('confirmation')},body:file});
      const result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to restore this backup.');
      await refresh();render();notify('Backup restored. Previous records kept in the safety-copies folder.');
    });
    $('#dialog button[type=submit]').textContent='Restore backup';
  };
}
$('#quit').onclick=async()=>{if(document.querySelector('#main form, dialog[open]')&&!confirm('An editor is open. Quit and discard any unsaved changes?'))return;editorDirty=false;try{await api('/api/shutdown',{});if(window.webkit?.messageHandlers?.localbooks)window.webkit.messageHandlers.localbooks.postMessage('quit');else $('#main').innerHTML='<div class="card"><h1>LocalBooks is closed</h1><p>Your records are saved on this Mac. You can close this browser tab.</p><p>Double-click the LocalBooks app to reopen.</p></div>'}catch(e){notify(e.message,true)}};
window.addEventListener('hashchange',route);refresh().then(route).catch(e=>{$('#main').innerHTML=`<div class="card"><h1>Open LocalBooks from its launcher</h1><p>${esc(e.message)}</p></div>`});

for(const event of ['input','change'])document.addEventListener(event,e=>{if(e.isTrusted&&e.target.closest('#main form,.paper-tools'))editorDirty=true});
document.addEventListener('click',e=>{if(e.target.closest('#doc-add,#catalog-add,.remove-doc-line'))editorDirty=true});
window.addEventListener('beforeunload',e=>{if(editorDirty){e.preventDefault();e.returnValue=''}});
